package render

import (
	"os/exec"
	"strings"
	"testing"
)

// probe/rbac-unmanaged.sh's user-authority section: a binding of an openinfra:* user or group in any
// namespace is a finding unless it is generated by the iam-compiler, the pinned break-glass binding, or
// acknowledged — a legacy tier is a finding (the IAM cutover deleted them) and a break-glass binding with
// any other subject is a finding too, as is
// a binding named like the old group or grant compositions' (no composition renders a user binding).
func TestRBACUnmanagedProbe_UserAuthority(t *testing.T) {
	needJQ(t)
	if _, err := exec.LookPath("bash"); err != nil {
		t.Skip("bash not installed")
	}
	tracked := func(name string) map[string]any {
		return map[string]any{"argocd.argoproj.io/tracking-id": "platform:rbac.authorization.k8s.io/ClusterRoleBinding:argocd/" + name}
	}
	bind := func(kind, name string) map[string]any {
		return map[string]any{"roleRef": map[string]any{"kind": "ClusterRole", "name": "open-infra-console"},
			"subjects": []any{map[string]any{"kind": kind, "name": name}}}
	}
	ctl := []string{"argocd-controller"}
	role := rbacObj("ClusterRole", "", "open-infra-console", ctl, nil, map[string]any{"argocd.argoproj.io/tracking-id": "platform:rbac.authorization.k8s.io/ClusterRole:argocd/open-infra-console"},
		map[string]any{"rules": []any{}})
	cluster := items(
		role,
		// allowed
		rbacObj("ClusterRoleBinding", "", "openinfra-root-break-glass", ctl, nil, tracked("openinfra-root-break-glass"), bind("User", "openinfra:000000000000:root")),
		rbacObj("ClusterRoleBinding", "", "open-infra-admins", ctl, map[string]any{"openinfra.dev/legacy": "true"}, tracked("open-infra-admins"), bind("Group", "openinfra:admins")),
		rbacObj("ClusterRoleBinding", "", "openinfra-iam:000000000000:user:alice", []string{"iam-compiler"},
			map[string]any{"openinfra.dev/generated-by": "iam-compiler"}, nil, bind("User", "openinfra:000000000000:alice")),
		rbacObj("ClusterRoleBinding", "", "platform-sa", ctl, nil, tracked("platform-sa"), bind("ServiceAccount", "x")),
		// findings
		rbacObj("ClusterRoleBinding", "", "openinfra-group-readers", []string{"crossplane-kubernetes-provider"}, nil, nil, bind("Group", "openinfra:readers")),
		rbacObj("ClusterRoleBinding", "", "openinfra-grant-jit", []string{"crossplane-kubernetes-provider"}, nil, nil, bind("User", "openinfra:alice")),
		rbacObj("ClusterRoleBinding", "", "sneaky-tier", ctl, nil, tracked("sneaky-tier"), bind("Group", "openinfra:powerusers")),
		rbacObj("ClusterRoleBinding", "", "openinfra-root-break-glass-2", ctl, nil, tracked("openinfra-root-break-glass-2"), bind("User", "openinfra:root")),
	)
	cluster["items"] = append(cluster["items"].([]any),
		// the break-glass name with a different subject is not the break-glass binding
		rbacObj("ClusterRoleBinding", "", "openinfra-root-break-glass", ctl, nil, tracked("openinfra-root-break-glass"), bind("User", "openinfra:alice")))
	ns := items(
		rbacObj("RoleBinding", "team-a", "hand-user", ctl, nil, nil, bind("User", "openinfra:912345678901:dana")),
		rbacObj("RoleBinding", "team-a", "acked", ctl, nil, map[string]any{"openinfra.dev/rbac-unmanaged-reason": "one engagement"}, bind("Group", "openinfra:mirror")),
	)
	apps := items(map[string]any{"metadata": map[string]any{"namespace": "argocd", "name": "platform"}, "status": map[string]any{}})
	out, code, calls := runRBACProbe(t, cluster, ns, items(), apps)
	if code != 1 {
		t.Fatalf("user authority outside the generated set must fail the probe; exit=%d\n%s", code, out)
	}
	var found []string
	for _, ln := range strings.Split(out, "\n") {
		if strings.HasPrefix(ln, "✗ ") && strings.Contains(ln, " — roleRef ") {
			found = append(found, strings.SplitN(strings.TrimPrefix(ln, "✗ "), " — ", 2)[0])
		}
	}
	want := []string{
		"ClusterRoleBinding/open-infra-admins",
		"ClusterRoleBinding/openinfra-grant-jit",
		"ClusterRoleBinding/openinfra-group-readers",
		"ClusterRoleBinding/openinfra-root-break-glass",
		"ClusterRoleBinding/openinfra-root-break-glass-2",
		"ClusterRoleBinding/sneaky-tier",
		"RoleBinding/team-a/hand-user",
	}
	if strings.Join(found, ",") != strings.Join(want, ",") {
		t.Errorf("user-authority findings:\n  %s\nwant:\n  %s\noutput:\n%s", strings.Join(found, "\n  "), strings.Join(want, "\n  "), out)
	}
	assertReadOnlyCalls(t, calls)
}
